import hashlib
import json
from fractions import Fraction
from pathlib import Path

import numpy as np

ROOT = Path(__file__).resolve().parents[2]
PATHS = ['ada/v2-certified-heldout-results.json', 'ada/v2-fold-results.json',
         'branches/branch-3/ada/v2_wl_results_t40.json']
held, reported, quartet = [json.loads((ROOT / p).read_text()) for p in PATHS]
# Q SI Tables S3/S4, branches/branch-3/emmy/review-sources/q-si.txt:182-257.
targets = {'3C':-.2,'3D':-.6,'3E':0.,'3G':-1.1,'3H':-1.5,'3I':-.9,
           '3J':-1.6,'3K':-.9,'5C':-.9,'5D':-1.5,'5E':-2.1,'5G':-2.6,
           '5H':-2.6,'5I':-3.2,'5J':-3.4,'5K':-3.1}
labels = list(targets)
y = np.array([targets[l] for l in labels])
series = np.array([[int(l[0]=='3'), int(l[0]=='5')] for l in labels])
tags = ['3HAC', '8SKH', '5F4L']
summaries = []
max_error = 0.
def check(a, b):
    global max_error
    delta = float(np.max(np.abs(np.asarray(a)-np.asarray(b))))
    max_error = max(max_error, delta)
    assert delta < 1e-10, delta

for i, tag in enumerate(tags):
    runs = [held['ligands'][l]['runs'][i] for l in labels]
    assert all(r['status']==0 and r['gap']==0 for r in runs)
    assert all(abs(r['W']-r['dual_bound']) < 1e-5 for r in runs)
    w = np.array([r['W'] for r in runs])
    result = reported['settings'][i]
    predictions = {m:[] for m in ['mean','decreasing_centred','unconstrained']}
    slopes = []
    for j, label in enumerate(labels):
        train = np.arange(len(labels)) != j
        design = np.column_stack((series, w))
        fit = np.linalg.lstsq(design[train], y[train], rcond=None)[0]
        slopes.append(fit[2])
        baseline = y[train & (series[:,0]==series[j,0])].mean()
        predictions['mean'].append(baseline)
        predictions['unconstrained'].append(design[j] @ fit)
        predictions['decreasing_centred'].append(baseline if fit[2]>0 else design[j] @ fit)
    for m in ['mean','decreasing_centred']:
        check(predictions[m], [float(Fraction(result['predictions_exact'][m][l])) for l in labels])
    rmse = {m:float(np.sqrt(np.mean((np.array(p)-y)**2))) for m,p in predictions.items()}
    check(rmse['unconstrained'], result['unconstrained_centred_rmse'])
    check([min(slopes),max(slopes)], [float(Fraction(v)) for v in result['loo_unconstrained_centred_slope_range']])
    origin_errors = []
    def saved(label):
        return quartet['runs']['own5A|'+tag+'|'+label]['W']
    for row in result['alternate_source_scenarios']:
        a3, a5, b3 = row['sources']
        refs = np.array([saved(b3) if l[0]=='3' else saved('5B') for l in labels])
        x = w-refs
        pred = []
        for j in range(len(labels)):
            train = np.arange(len(labels)) != j
            fit = np.linalg.lstsq(x[train,None], y[train], rcond=None)[0][0]
            pred.append(fit*x[j])
        mse = float(np.mean((np.array(pred)-y)**2))
        check(mse, float(Fraction(row['mse_origin'])))
        origin_errors.append(mse**.5)
        slope = np.linalg.lstsq(x[:,None], y, rcond=None)[0][0]
        check(slope, float(Fraction(row['b'])))
        for c in ['A','F']:
            raw = saved(a5 if c=='A' else '5F')-saved('5B')-saved(a3 if c=='A' else '3F')+saved(b3)
            check(slope*raw, float(Fraction(row[c])))
    assert len(origin_errors)==8
    summaries.append({'setting':result['setting'], 'fold_rmse':rmse,
                      'all_16_fold_slopes_positive': bool(min(slopes)>0),
                      'alternate_origin_rmse_range':[min(origin_errors),max(origin_errors)],
                      'source_scenarios_checked':len(origin_errors)})

out = {'scope':'Independent NumPy design-matrix recomputation, saved declared-model scores only; no independent chemical or solver certification.',
       'input_sha256':{p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in PATHS},
       'script_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
       'max_absolute_disagreement':max_error, 'settings':summaries}
(ROOT/'emmy/heldout/v2-partner-check-results.json').write_text(json.dumps(out,indent=2)+'\n')
print(json.dumps(out,indent=2))
