import sys, json, re, itertools, time
import numpy as np, networkx as nx
from scipy.optimize import milp, LinearConstraint, Bounds
from scipy.sparse import coo_matrix
SYS, OUT = sys.argv[1], sys.argv[2]
def read_top(p):
    fl, cur, fmt = {}, None, None
    for line in open(p):
        if line.startswith('%FLAG'): cur = line.split()[1]; fl[cur] = []; continue
        if line.startswith('%FORMAT'): fmt = line; continue
        if cur is None or line.startswith('%'): continue
        if 'a4' in fmt: fl[cur] += [line[i:i+4].strip() for i in range(0, len(line.rstrip('\n')), 4)]
        else: fl[cur] += line.split()
    return fl
def read_crd(p, n):
    L = open(p).read().splitlines()[2:]
    v = []
    for l in L:
        v += [float(l[i:i+12]) for i in range(0, len(l), 12) if l[i:i+12].strip()]
        if len(v) >= 3*n: break
    return np.array(v[:3*n]).reshape(n, 3)
def read_pert(p):
    d, name = {}, None
    for l in open(p):
        s = l.split()
        if not s: continue
        if s[0] == 'name': name = s[1]
        if s[0] in ('initial_type', 'final_type'): d.setdefault(name, {})[s[0]] = s[1]
    return d
def elem(t):
    t = t.lower()
    if t.startswith('cl'): return 'Cl'
    if t.startswith('br'): return 'Br'
    return t[0].upper()
def load(dirname):
    base = f"{SYS}/{dirname}/Complex/core/"
    top = read_top(base+'SYSTEM.top'); n = int(top['POINTERS'][0])
    xyz = read_crd(base+'SYSTEM.crd', n)
    names, types = top['ATOM_NAME'][:n], top['AMBER_ATOM_TYPE'][:n]
    rl, rp = top['RESIDUE_LABEL'], [int(x)-1 for x in top['RESIDUE_POINTER']]
    res = np.zeros(n, int)
    for i, s in enumerate(rp): res[s:] = i
    bonds = [[] for _ in range(n)]
    for k in ('BONDS_INC_HYDROGEN', 'BONDS_WITHOUT_HYDROGEN'):
        b = [int(x) for x in top[k]]
        for i in range(0, len(b), 3):
            a, c = b[i]//3, b[i+1]//3; bonds[a].append(c); bonds[c].append(a)
    return dict(xyz=xyz, names=names, types=types, rl=rl, res=res, bonds=bonds, pert=read_pert(base+'MORPH.pert'), n=n)
AROM_P = {'CA', 'CB', 'CN', 'C*'}
def rings6(idx, bonds, ok):
    out = set()
    for a in idx:
        def dfs(path):
            if len(path) == 6:
                if path[0] in bonds[path[-1]]: out.add(frozenset(path))
                return
            for b in bonds[path[-1]]:
