def features(S, atoms, typ, ligand):
    """atoms: candidate indices; typ: dict index->type for those atoms (dummies already removed)."""
    E = {i: elem(typ[i]) for i in atoms}
    nb = {i: [j for j in S['bonds'][i] if j in typ] for i in atoms}
    nH = {i: sum(E.get(j) == 'H' for j in nb[i]) for i in atoms}
    pts = []
    for i in atoms:
        e, t = E[i], typ[i]
        if e in ('N', 'O') and nH[i] >= 1: pts.append(('HD', S['xyz'][i], i))
        if e == 'O' or (ligand and t in ('nb', 'nc', 'nd')) or (not ligand and t == 'NB'): pts.append(('HA', S['xyz'][i], i))
        if e in ('Cl', 'Br') or (e == 'S' and not ligand): pts.append(('HP', S['xyz'][i], i))
        if e == 'C' and nH[i] == 3 and all(E[j] in ('C', 'H') for j in nb[i]) and (t in ('c3', 'CT')): pts.append(('HP', S['xyz'][i], i))
    arom = (lambda b: b in typ and typ[b] == 'ca') if ligand else (lambda b: b in typ and typ[b] in AROM_P)
    for r in rings6([i for i in atoms if arom(i)], S['bonds'], arom):
