  "branches/branch-3/emmy/transfer-audit/audit.py": """"Declared safe thrombin transfer model. Reads archive data, never imported code.

Run with uv run --no-project --with rdkit --with networkx python this-file.
Endpoint chemistry gates precede graph optimisation. Scores have native units.
"""
import hashlib
import itertools
import json
import random
import re
import tarfile
import time
from collections import Counter
from pathlib import Path

import networkx as nx
import numpy as np
from rdkit import Chem, RDConfig, rdBase
from rdkit.Chem import ChemicalFeatures, rdMolDescriptors

OUT = Path(__file__).parent
ARCHIVE = Path('ada/thrombin-source/inputs.tar.gz')
SOURCES = {'3A': ('3D~3A', 'final'), '3B': ('3C~3B', 'final'),
           '3F': ('3F~3C', 'initial'), '5A': ('5B~5A', 'final'),
           '5B': ('5B~5A', 'initial'), '5F': ('5F~5C', 'initial')}
PREFIX = {'A': 'CC(=O)', 'B': 'CCC(=O)', 'F': 'CC(C)CCC(=O)'}
PREFIX5 = {'A': '[NH3+]CC(=O)', 'B': 'CC([NH3+])C(=O)',
           'F': 'CC(C)CC([NH3+])C(=O)'}
TAIL = 'N1CCCC1C(=O)NCc1cccc(Cl)c1'
FAMILIES = {'Donor': 'HD', 'Acceptor': 'HA', 'Hydrophobe': 'HP',
            'LumpedHydrophobe': 'HP', 'Aromatic': 'AR'}
ORDER = ['HD', 'HA', 'HP', 'AR']
WEIGHTS = [[5244,6686,1453,1091], [6686,5478,2317,770],
           [1453,2317,504,795], [1091,770,795,1943]]
SETTINGS = [(3.1,2.5,0.1), (4.0,3.0,0.6), (2.8,2.5,0.1)]

def sha(b):
    return hashlib.sha256(b).hexdigest()

def topology(text):
    blocks = {}
    for m in re.finditer(r'%FLAG (\w+)\s*\n%FORMAT\((\d+)([a-zA-Z])(\d+)(?:\.\d+)?\)\s*\n(.*?)(?=%FLAG|\Z)', text, re.S):
        name, _, typ, width, data = m.groups()
        fields = [s[i:i+int(width)].strip() for s in data.splitlines()
                  for i in range(0, len(s), int(width)) if s[i:i+int(width)].strip()]
        blocks[name] = fields if typ.lower() == 'a' else [float(x.replace('D','E')) if typ.lower() == 'e' else int(x) for x in fields]
    return blocks

def element(typ, name):
    if typ == 'du': return None
    if typ.lower() in ['cl', 'br']: return typ.title()
    if typ[0].lower() in 'hcnosfp': return typ[0].upper()
    if name[:2].strip().title() in ['Na','Cl']: return name[:2].strip().title()
    raise ValueError(('unknown element', typ, name))

def read_system(tar, label):
    edge, state = SOURCES[label]
    base = f'Systems/{label[0]}Series/{edge}/Complex/core/'
    raw = {f: tar.extractfile(base+f).read() for f in ['SYSTEM.pdb','SYSTEM.top','MORPH.pert']}
    top = topology(raw['SYSTEM.top'].decode())
    pdb = [s for s in raw['SYSTEM.pdb'].decode().splitlines() if s.startswith(('ATOM  ','HETATM'))]
    names = top['ATOM_NAME']; types = top['AMBER_ATOM_TYPE']
    assert len(pdb) == len(names) == top['POINTERS'][0]
    assert [s[12:16].strip() for s in pdb] == names
    nlig = top['RESIDUE_POINTER'][1]-1
    coords = np.array([[float(s[a:b]) for a,b in [(30,38),(38,46),(46,54)]] for s in pdb])
    rows = {d['name']: d for a in re.findall(r'\n\s*atom\s*\n(.*?)\n\s*endatom', raw['MORPH.pert'].decode(), re.S)
            if (d := dict(re.findall(r'^\s*(name|initial_type|final_type|initial_charge|final_charge)\s+(\S+)',a,re.M)))}
    typ = types[:nlig].copy()
    for i in range(nlig):
        if names[i] in rows:
            assert types[i] == rows[names[i]]['initial_type']
            typ[i] = rows[names[i]][state+'_type']
    bonds = set()
    for key in ['BONDS_INC_HYDROGEN','BONDS_WITHOUT_HYDROGEN']:
        arr = top[key]
        for i in range(0,len(arr),3):
            bonds.add(tuple(sorted((int(arr[i])//3,int(arr[i+1])//3))))
    active = [i for i in range(nlig) if typ[i] != 'du']
    elem = [element(typ[i],names[i]) for i in active]
    mol = Chem.RWMol(); index = {}
    for i,e in zip(active,elem):
        a = Chem.Atom(e); a.SetNoImplicit(True)
        if typ[i] == 'n4': a.SetFormalCharge(1)
        index[i] = mol.AddAtom(a)
    for i,j in sorted(bonds):
        if i not in index or j not in index: continue
        a,b = typ[i],typ[j]
        bt = Chem.BondType.SINGLE
        if {a,b} == {'c','o'}: bt = Chem.BondType.DOUBLE
        elif a == b == 'ca': bt = Chem.BondType.AROMATIC
        mol.AddBond(index[i],index[j],bt)
    m = mol.GetMol(); Chem.SanitizeMol(m)
    cf = Chem.Conformer(len(active))
    for i,k in index.items(): cf.SetAtomPosition(k,coords[i])
    m.AddConformer(cf)
    sm = Chem.MolToSmiles(Chem.RemoveHs(m),isomericSmiles=False)
    expected = Chem.MolToSmiles(Chem.MolFromSmiles((PREFIX5 if label[0]=='5' else PREFIX)[label[1]]+TAIL),isomericSmiles=False)
    assert sm == expected, (label,sm,expected)
    formula = rdMolDescriptors.CalcMolFormula(m)
    # Protein atom keys are topology residue positions relative to ligand residue.
    keys = {}; residues = top['RESIDUE_LABEL']; ptr = top['RESIDUE_POINTER']+[len(names)+1]
    for r in range(1,len(residues)):
        if residues[r] in ['WAT','Na+','Cl-']: continue
        for i in range(ptr[r]-1,ptr[r+1]-1):
            if element(types[i],names[i]) != 'H': keys[(r,residues[r],names[i])] = i
    meta = {'source_member_base':base,'state':state,'lambda':0 if state=='initial' else 1,
            'member_hashes':{f:sha(b) for f,b in raw.items()}, 'topology_natoms':len(names),
            'morph_natoms':nlig,'active_atoms':len(active),'removed_dummy_atoms':nlig-len(active),
            'canonical_nonstereo_smiles':sm,'expected_nonstereo_smiles':expected,'formula':formula,
            'name_count_initial_type_checks':True,'identity_graph_check':True,
            'final_coordinate_caveat':state=='final',
            'known_solvent_duplication_used':False,
            'atom_manifest':[{'top_index':i,'name':names[i],'type':typ[i],
                              'element':element(typ[i],names[i])} for i in active]}
    return {'mol':m,'active':active,'coords':coords,'top':top,'bonds':bonds,
            'keys':keys,'nlig':nlig,'meta':meta}

def ligand_features(system, transform):
    factory = ChemicalFeatures.BuildFeatureFactory(str(Path(RDConfig.RDDataDir)/'BaseFeatures.fdef'))
    feats = []
    for f in factory.GetFeaturesForMol(system['mol']):
        if f.GetFamily() not in FAMILIES: continue
        ids = list(f.GetAtomIds()); orig = [system['active'][i] for i in ids]
        pos = system['coords'][orig].mean(axis=0)
        pos = (pos-transform[0]) @ transform[2]+transform[1]
        feats.append({'family':FAMILIES[f.GetFamily()],'rdkit_family':f.GetFamily(),
                      'atoms':orig,'coords':pos.tolist()})
    return sorted(feats,key=lambda f:(f['family'],f['atoms']))

def receptor_features(ref):
    top = ref['top']; names=top['ATOM_NAME']; types=top['AMBER_ATOM_TYPE']
    ids = set(ref['keys'].values()); neigh = {i:[] for i in range(len(names))}
    for i,j in ref['bonds']: neigh[i].append(j); neigh[j].append(i)
    points=[]
    def add(fam, atoms):
        points.append({'family':fam,'atoms':sorted(atoms),'coords':ref['coords'][atoms].mean(axis=0).tolist()})
    for i in sorted(ids):
        e = element(types[i],names[i])
        hs = [j for j in neigh[i] if element(types[j],names[j])=='H']
        if e in ['N','O'] and hs: add('HD',[i])
        if e=='O' and not hs: add('HA',[i])
        if e=='C' and types[i] not in ['C','c']: add('HP',[i])
    graph=nx.Graph(); graph.add_nodes_from(i for i in ids if types[i] in ['CA','ca'])
    graph.add_edges_from((i,j) for i,j in ref['bonds'] if i in graph and j in graph)
    for ring in nx.cycle_basis(graph):
        if len(ring)==6: add('AR',ring)
    heavy=ref['coords'][[i for i in ref['active'] if element(types[i],names[i])!='H']]
    for p in points:
        p['selection_distance']=float(np.linalg.norm(heavy-np.array(p['coords']),axis=1).min())
        p['atom_names']=[names[i] for i in p['atoms']]
    points.sort(key=lambda p:(p['selection_distance'],p['family'],p['atoms']))
    return points[:4],len(points)

def align(system,ref):
    keys=sorted(set(system['keys']) & set(ref['keys']))
    a=system['coords'][[system['keys'][k] for k in keys]]
    b=ref['coords'][[ref['keys'][k] for k in keys]]
    ac,bc=a.mean(axis=0),b.mean(axis=0)
    u,_,vt=np.linalg.svd((a-ac).T@(b-bc)); corr=np.eye(3)
    corr[-1,-1]=np.linalg.det(u@vt); rot=u@corr@vt
    rms=float(np.sqrt(np.mean(np.sum(((a-ac)@rot+bc-b)**2,axis=1))))
    return (ac,bc,rot),{'common_protein_heavy_atoms':len(keys),'rmsd_angstrom':rms}

def exact_clique(adj,weights):
    best=0; witness=[]; nodes=0; start=time.monotonic()
    def colour_bound(candidates):
        classes=[]; maxima=[]
        for v in sorted(candidates,key=lambda x:(-weights[x],x)):
            for k,c in enumerate(classes):
                if not any(adj[v]>>u&1 for u in c):
                    c.append(v); maxima[k]=max(maxima[k],weights[v]); break
            else: classes.append([v]); maxima.append(weights[v])
        return sum(maxima)
    def visit(candidates,value,selected):
        nonlocal best,witness,nodes
        nodes+=1
        if time.monotonic()-start>120: raise TimeoutError('exact search incomplete')
        if value>best: best=value; witness=selected.copy()
        while candidates:
            if value+colour_bound(candidates)<=best:return
            v=max(candidates,key=lambda x:(sum(adj[x]>>u&1 for u in candidates),weights[x],-x))
            candidates.remove(v)
            visit([u for u in candidates if adj[v]>>u&1],value+weights[v],selected+[v])
    visit(list(range(len(weights))),0,[])
    assert sum(weights[i] for i in witness)==best
    assert all(adj[i]>>j&1 for i,j in itertools.combinations(witness,2))
    return {'weight_integer':best,'weight_native':best/10000,'witness_vertices':witness,
            'search_nodes':nodes,'wall_seconds':time.monotonic()-start,'complete':True}

def solver_checks():
    rng=random.Random(20261007); checked=0
    for n in range(11):
        for prob in [0,0.2,0.5,0.8,1]:
            a=[0]*n; w=[rng.randrange(1,10) for _ in range(n)]
            for i,j in itertools.combinations(range(n),2):
                if rng.random()<prob:a[i]|=1<<j;a[j]|=1<<i
            exact=0
            for bits in range(1<<n):
                inds=[i for i in range(n) if bits>>i&1]
                if all(a[i]>>j&1 for i,j in itertools.combinations(inds,2)):
                    exact=max(exact,sum(w[i] for i in inds))
            assert exact_clique(a,w)['weight_integer']==exact
            checked+=1
    return {'exhaustive_graphs':checked,'seed':20261007,'passed':True}

def big(ligand,receptor,setting):
    eps,epss,tau=setting
    vertices=[]; w=[]
    for i,l in enumerate(ligand):
        for j,p in enumerate(receptor):
            d=epss if {l['family'],p['family']}=={'HD','HA'} else eps
            vertices.append({'ligand_feature':i,'receptor_feature':j,'epsilon':d})
            w.append(WEIGHTS[ORDER.index(l['family'])][ORDER.index(p['family'])])
    adj=[0]*len(w)
    for i,j in itertools.combinations(range(len(w)),2):
        v,u=vertices[i],vertices[j]
        dl=np.linalg.norm(np.array(ligand[v['ligand_feature']]['coords'])-ligand[u['ligand_feature']]['coords'])
        dp=np.linalg.norm(np.array(receptor[v['receptor_feature']]['coords'])-receptor[u['receptor_feature']]['coords'])
        if abs(dl-dp)<tau+v['epsilon']+u['epsilon']:
            adj[i]|=1<<j;adj[j]|=1<<i
    graph={'vertices':vertices,'weights_integer':w,'adjacency_bitsets':[hex(x) for x in adj]}
    result=exact_clique(adj,w);result.update({'vertex_count':len(w),
         'edge_count':sum(x.bit_count() for x in adj)//2,'graph_sha256':sha(json.dumps(graph,sort_keys=True).encode())})
    return graph,result

def main():
    result={'scope':'Declared reduced contact model, not free-energy prediction or P/Q reproduction.',
            'archive_sha256':sha(ARCHIVE.read_bytes()),'archive_source_url':'https://ndownloader.figshare.com/files/5385146',
